interface Component { update(entity: Entity, dt: number): void }

export class Entity {
  private parts = new Map<Function, Component>();
  add<T extends Component>(c: T): this { this.parts.set(c.constructor, c); return this; }
  get<T extends Component>(ctor: new (...a: never[]) => T): T | undefined {
    return this.parts.get(ctor) as T | undefined;
  }
  update(dt: number) { this.parts.forEach((c) => c.update(this, dt)); }
}

const bjorn = new Entity().add(new PlayerInput()).add(new Physics());
